Here is a complete, production-ready implementation of a generic `Stack<T>` in C# backed by a dynamic array. 

It includes automatic resizing (doubling when full, halving when too empty to save memory), input validation, generic constraints awareness, and implements `IEnumerable<T>` so you can use it in `foreach` loops.

### The Code

```csharp
using System;
using System.Collections;
using System.Collections.Generic;

public class CustomStack<T> : IEnumerable<T>
{
    private T[] _array;
    private int _size;
    private const int DefaultCapacity = 4;

    /// <summary>
    /// Gets the number of elements contained in the Stack.
    /// </summary>
    public int Count => _size;

    /// <summary>
    /// Gets the total number of elements the internal array can hold without resizing.
    /// </summary>
    public int Capacity => _array.Length;

    /// <summary>
    /// Initializes a new instance of the CustomStack class that is empty and has the default initial capacity.
    /// </summary>
    public CustomStack()
    {
        _array = new T[DefaultCapacity];
        _size = 0;
    }

    /// <summary>
    /// Initializes a new instance of the CustomStack class that is empty and has the specified initial capacity.
    /// </summary>
    public CustomStack(int capacity)
    {
        if (capacity < 0)
            throw new ArgumentOutOfRangeException(nameof(capacity), "Capacity must be non-negative.");

        _array = new T[Math.Max(capacity, DefaultCapacity)];
        _size = 0;
    }

    /// <summary>
    /// Inserts an object at the top of the CustomStack.
    /// </summary>
    public void Push(T item)
    {
        if (_size == _array.Length)
        {
            // Double the capacity when the array is full
            Resize(_array.Length * 2);
        }

        _array[_size++] = item;
    }

    /// <summary>
    /// Removes and returns the object at the top of the CustomStack.
    /// </summary>
    public T Pop()
    {
        if (_size == 0)
            throw new InvalidOperationException("Stack is empty.");

        int topIndex = --_size;
        T item = _array[topIndex];

        // Clear the reference to allow Garbage Collection
        _array[topIndex] = default!; 

        // Optional: Shrink array if it's only 25% full to save memory
        if (_size > DefaultCapacity && _size < _array.Length / 4)
        {
            Resize(_array.Length / 2);
        }

        return item;
    }

    /// <summary>
    /// Returns the object at the top of the CustomStack without removing it.
    /// </summary>
    public T Peek()
    {
        if (_size == 0)
            throw new InvalidOperationException("Stack is empty.");

        return _array[_size - 1];
    }

    /// <summary>
    /// Removes all objects from the CustomStack.
    /// </summary>
    public void Clear()
    {
        // Clear elements so GC can reclaim memory
        Array.Clear(_array, 0, _size);
        _size = 0;
    }

    /// <summary>
    /// Determines whether an element is in the CustomStack.
    /// </summary>
    public bool Contains(T item)
    {
        EqualityComparer<T> comparer = EqualityComparer<T>.Default;
        for (int i = 0; i < _size; i++)
        {
            if (comparer.Equals(_array[i], item))
            {
                return true;
            }
        }
        return false;
    }

    /// <summary>
    /// Helper method to resize the internal array.
    /// </summary>
    private void Resize(int newCapacity)
    {
        T[] newArray = new T[newCapacity];
        Array.Copy(_array, 0, newArray, 0, _size);
        _array = newArray;
    }

    /// <summary>
    /// Returns an enumerator that iterates through the CustomStack (LIFO order).
    /// </summary>
    public IEnumerator<T> GetEnumerator()
    {
        // Iterate from top to bottom
        for (int i = _size - 1; i >= 0; i--)
        {
            yield return _array[i];
        }
    }

    IEnumerator IEnumerable.GetEnumerator()
    {
        return GetEnumerator();
    }
}
```

### Example Usage

```csharp
class Program
{
    static void Main()
    {
        CustomStack<string> stack = new CustomStack<string>();

        // Pushing elements
        stack.Push("First");
        stack.Push("Second");
        stack.Push("Third");

        Console.WriteLine($"Count: {stack.Count}, Capacity: {stack.Capacity}"); // Count: 3, Capacity: 4

        // Peeking
        Console.WriteLine($"Top element: {stack.Peek()}"); // Third

        // Popping elements (LIFO order)
        Console.WriteLine($"Popped: {stack.Pop()}"); // Third
        Console.WriteLine($"Popped: {stack.Pop()}"); // Second

        // Using foreach (Enumerates from top to bottom)
        stack.Push("Fourth");
        Console.WriteLine("\nCurrent Stack contents:");
        foreach (var item in stack)
        {
            Console.WriteLine(item);
        }
        // Output: 
        // Fourth
        // First
    }
}
```

### Key Design Features:
1. **Dynamic Resizing (Amortized $O(1)$ insertions):** When the stack exceeds its capacity, `Array.Copy` is used to double the array size. This ensures `Push` runs in amortized constant time.
2. **Memory Leak Prevention (`_array[topIndex] = default!`):** In C#, reference types stored in an array will keep holding memory references even after "removal" unless explicitly nulled out. Setting it to `default!` allows the Garbage Collector to clean up abandoned objects.
3. **Memory Shrinking:** The stack halves its internal array size if utilization drops below 25%, preventing memory bloat after large operations.
4. **`IEnumerable<T>` Implementation:** Allows integration with LINQ and standard `foreach` loops, traversing from the top of the stack down to the bottom.
